import numpy as np, itertools
c = np.loadtxt('complex_opt2.xyz', skiprows=2, usecols=(1,2,3))
elems = [l.split()[0] for l in open('complex_opt2.xyz').readlines()[2:]]
cov = {'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Cl':1.02,'Ru':1.46}
n=len(elems)
bonds=set()
D = np.linalg.norm(c[:,None,:]-c[None,:,:],axis=2)
for i,j in itertools.combinations(range(n),2):
    if D[i,j] < cov[elems[i]]+cov[elems[j]]+0.4:
        bonds.add((i,j))
# 1-3
one3=set()
for (i,j) in bonds:
    for (k,l) in bonds:
        if j==k and i!=l: one3.add(tuple(sorted((i,l))))
bad=[]
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonds or (i,j) in one3: continue
    if D[i,j]<1.9: bad.append((round(D[i,j],2),i,elems[i],j,elems[j]))
bad.sort()
print("nonbonded close contacts <1.9:")
for b in bad[:12]: print(b)
EOF
